        // inline-only batch core — a real call would address-expose the batch
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool WriteNarrowBodyData_ShallowBatch(ref WriteBatch batch, NarrowBodyData_Shallow value)
        {
            if (value.PositionX < -25600000 || value.PositionX > 25600000)
            {
                return false;
            }
            {
                uint offsetValue = (uint)(value.PositionX) - unchecked((uint)(-25600000));
                if (!batch.SerializeBits(ref offsetValue, 26))
                {
                    return false;
                }
            }
            if (value.PositionY < -25600000 || value.PositionY > 25600000)
            {
                return false;
            }
            {
                uint offsetValue = (uint)(value.PositionY) - unchecked((uint)(-25600000));
                if (!batch.SerializeBits(ref offsetValue, 26))
                {
                    return false;
                }
            }
            if (value.PositionZ < -25600000 || value.PositionZ > 25600000)
            {
                return false;
            }
            {
                uint offsetValue = (uint)(value.PositionZ) - unchecked((uint)(-25600000));
                if (!batch.SerializeBits(ref offsetValue, 26))
                {
                    return false;
                }
            }
            if (value.RotationX < -1024 || value.RotationX > 1024)
            {
                return false;
            }
            {
                uint offsetValue = (uint)(value.RotationX) - unchecked((uint)(-1024));
                if (!batch.SerializeBits(ref offsetValue, 12))
                {
                    return false;
                }
            }
            if (value.RotationY < -1024 || value.RotationY > 1024)
            {
                return false;
            }
            {
                uint offsetValue = (uint)(value.RotationY) - unchecked((uint)(-1024));
                if (!batch.SerializeBits(ref offsetValue, 12))
                {
                    return false;
                }
            }
            if (value.RotationZ < -1024 || value.RotationZ > 1024)
            {
                return false;
            }
            {
                uint offsetValue = (uint)(value.RotationZ) - unchecked((uint)(-1024));
                if (!batch.SerializeBits(ref offsetValue, 12))
                {
                    return false;
                }
            }
            if (value.RotationW < -1024 || value.RotationW > 1024)
            {
                return false;
            }
            {
                uint offsetValue = (uint)(value.RotationW) - unchecked((uint)(-1024));
                if (!batch.SerializeBits(ref offsetValue, 12))
                {
                    return false;
                }
            }
            if (!WriteFixedVecBatch(ref batch, value.Velocity))
            {
                return false;
            }
            return true;
        }

        public static bool ReadNarrowBodyData_Shallow(ReadStream stream, NarrowBodyData_Shallow value)
        {
