        // inline-only batch core — a real call would address-expose the batch
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool ReadNarrowBodyData_ShallowBatch(ref ReadBatch batch, NarrowBodyData_Shallow value)
        {
            if (!batch.SerializeInt(ref value.PositionX, -25600000, 25600000))
            {
                return false;
            }
            if (!batch.SerializeInt(ref value.PositionY, -25600000, 25600000))
            {
                return false;
            }
            if (!batch.SerializeInt(ref value.PositionZ, -25600000, 25600000))
            {
                return false;
            }
            {
                int componentValue = 0;
                if (!batch.SerializeInt(ref componentValue, -1024, 1024))
                {
                    return false;
                }
                value.RotationX = (short)componentValue;
            }
            {
                int componentValue = 0;
                if (!batch.SerializeInt(ref componentValue, -1024, 1024))
                {
                    return false;
                }
                value.RotationY = (short)componentValue;
            }
            {
                int componentValue = 0;
                if (!batch.SerializeInt(ref componentValue, -1024, 1024))
                {
                    return false;
                }
                value.RotationZ = (short)componentValue;
            }
            {
                int componentValue = 0;
                if (!batch.SerializeInt(ref componentValue, -1024, 1024))
                {
                    return false;
                }
                value.RotationW = (short)componentValue;
            }
            if (!ReadFixedVecBatch(ref batch, value.Velocity))
            {
                return false;
            }
            return true;
        }

        public static void QuantizeNarrowBody(NarrowBodyData_Interpolate input, NarrowBodyData_Shallow output)
        {
            {
                long raw = (long)input.Position.X;
                output.PositionX = (int)(raw >= 0 ? (raw + 128) >> 8 : -((-raw + 128) >> 8));
            }
            {
                long raw = (long)input.Position.Y;
                output.PositionY = (int)(raw >= 0 ? (raw + 128) >> 8 : -((-raw + 128) >> 8));
            }
            {
                long raw = (long)input.Position.Z;
                output.PositionZ = (int)(raw >= 0 ? (raw + 128) >> 8 : -((-raw + 128) >> 8));
            }
            {
                long raw = (long)input.Rotation.X;
                output.RotationX = (short)(raw >= 0 ? (raw + 524288) >> 20 : -((-raw + 524288) >> 20));
            }
            {
                long raw = (long)input.Rotation.Y;
                output.RotationY = (short)(raw >= 0 ? (raw + 524288) >> 20 : -((-raw + 524288) >> 20));
            }
            {
                long raw = (long)input.Rotation.Z;
                output.RotationZ = (short)(raw >= 0 ? (raw + 524288) >> 20 : -((-raw + 524288) >> 20));
            }
            {
                long raw = (long)input.Rotation.W;
                output.RotationW = (short)(raw >= 0 ? (raw + 524288) >> 20 : -((-raw + 524288) >> 20));
            }
            output.Velocity.X = input.Velocity.X;
            output.Velocity.Y = input.Velocity.Y;
            output.Velocity.Z = input.Velocity.Z;
        }

        public static void UnquantizeNarrowBody(NarrowBodyData_Shallow input, NarrowBodyData_Interpolate output)
        {
            output.Position.X = (long)((long)input.PositionX << 8);
            output.Position.Y = (long)((long)input.PositionY << 8);
            output.Position.Z = (long)((long)input.PositionZ << 8);
            output.Rotation.X = (int)((long)input.RotationX << 20);
            output.Rotation.Y = (int)((long)input.RotationY << 20);
            output.Rotation.Z = (int)((long)input.RotationZ << 20);
            output.Rotation.W = (int)((long)input.RotationW << 20);
            output.Velocity.X = input.Velocity.X;
            output.Velocity.Y = input.Velocity.Y;
            output.Velocity.Z = input.Velocity.Z;
        }

        // The message tag wire: MessageType in [0, 1], minimal bits; None = 0 is a
        // valid wire value meaning *no message* — the stream terminator (SPEC §4.8).
        // The write folds the tag's bit count at generation time (byte-identical to
        // the ranged form); a tag outside the set is refused — bool alone.
        public static bool WriteMessageType(WriteStream stream, MessageType value)
        {
            uint tagValue = (uint)value;
            if (tagValue > 1)
            {
                return false;
            }
            return stream.SerializeBits(ref tagValue, 1);
        }

        public static bool ReadMessageType(ReadStream stream, ref MessageType value)
        {
            int tagValue = 0;
            if (!stream.SerializeInt(ref tagValue, 0, 1))
            {
                return false;
            }
            value = (MessageType)tagValue;
            return true;
        }

        // The message-level bound: the tag plus the largest message (SPEC §6.1);
        // MessageMaxBytes is rounded up to the 8-byte write-buffer granularity.
        public const long MessageMaxBits = 1206;
        public const long MessageMaxBytes = 152;

        public static bool WriteMessage(WriteStream stream, Message message)
        {
            switch (message)
            {
                case null:
                    return WriteMessageType(stream, MessageType.None); // the stream terminator (SPEC §4.8)
                case LudicrousState value:
                    if (!WriteMessageType(stream, MessageType.LudicrousState))
                    {
                        return false;
                    }
                    return WriteLudicrousState(stream, value);
                default:
                    return false; // not a generated message type; nothing was written
            }
        }

        public static bool ReadMessage(ReadStream stream, MessageStorage storage, out Message message)
        {
            message = null;
            MessageType tagValue = MessageType.None;
            if (!ReadMessageType(stream, ref tagValue))
            {
                return false;
            }
            switch (tagValue)
            {
                case MessageType.None:
                    return true; // the stream terminator (SPEC §4.8) — message stays null
                case MessageType.LudicrousState:
                    ZeroLudicrousState(storage.LudicrousState); // reused storage starts from the zero form, as the union does
                    if (!ReadLudicrousState(stream, storage.LudicrousState))
                    {
                        return false;
                    }
                    message = storage.LudicrousState;
                    return true;
                default:
                    // ReadMessageType already rejected tags past the set; the switch
                    // still needs the arm because enums are open storage
                    return false;
            }
        }

        // The object tag wire: ObjectType in [0, 2], minimal bits; None = 0 is the
        // null — the sentinel the surveyed baseline streams terminate with (SPEC §4.8).
        // The write folds the tag's bit count at generation time (byte-identical to
        // the ranged form); a tag outside the set is refused — bool alone.
        public static bool WriteObjectType(WriteStream stream, ObjectType value)
        {
            uint tagValue = (uint)value;
            if (tagValue > 2)
            {
                return false;
            }
            return stream.SerializeBits(ref tagValue, 2);
        }

        public static bool ReadObjectType(ReadStream stream, ref ObjectType value)
        {
            int tagValue = 0;
            if (!stream.SerializeInt(ref tagValue, 0, 2))
            {
                return false;
            }
            value = (ObjectType)tagValue;
            return true;
        }
    }

